from __future__ import annotations
import json,html
from pathlib import Path
from cbim_sdk import CBIMProject
from .models import ImportPlan,ConversionReport

def _safe_json(value):return json.dumps(value,ensure_ascii=False).replace('</','<\\/')

def build_studio_html(project:CBIMProject,plan:ImportPlan,report:ConversionReport)->str:
    p=_safe_json(project.model_dump(mode='json',exclude_computed_fields=True));pl=_safe_json(plan.model_dump(mode='json'));rp=_safe_json(report.model_dump(mode='json'))
    return '''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CompatibilizaBIM Studio</title><style>
*{box-sizing:border-box}body{margin:0;font-family:Inter,ui-sans-serif,system-ui;background:#f5f7fa;color:#13202b}header{height:64px;background:#111b24;color:white;display:flex;align-items:center;padding:0 24px;justify-content:space-between}.brand{font-weight:800;font-size:20px}.shell{display:grid;grid-template-columns:230px 1fr;height:calc(100vh - 64px)}nav{background:#fff;border-right:1px solid #dde3ea;padding:18px 12px}nav button{display:block;width:100%;text-align:left;border:0;background:transparent;padding:11px 12px;border-radius:8px;margin:3px 0;font-weight:650;color:#40505f;cursor:pointer}nav button.active{background:#e9f0f6;color:#102a43}main{overflow:auto;padding:26px}.page{display:none}.page.active{display:block}.title{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.grid{display:grid;grid-template-columns:repeat(4,minmax(140px,1fr));gap:12px}.card{background:white;border:1px solid #dde3ea;border-radius:12px;padding:16px}.metric{font-size:28px;font-weight:800}.muted{color:#6b7c8c}.source,.element,.rule{background:#fff;border:1px solid #dde3ea;border-radius:10px;padding:12px;margin:8px 0}.badge{display:inline-block;padding:3px 7px;border-radius:999px;background:#edf2f7;font-size:12px}.ok{background:#ddf5e8}.warn{background:#fff4d6}.bad{background:#ffe1e1}button.action{border:1px solid #ccd6df;background:#fff;padding:8px 11px;border-radius:8px;cursor:pointer}button.primary{background:#163a5f;color:#fff;border-color:#163a5f}input,select{padding:8px;border:1px solid #ccd6df;border-radius:7px}.review-layout{display:grid;grid-template-columns:1fr 360px;gap:14px;height:calc(100vh - 150px)}#canvasWrap{background:#0c1218;border-radius:12px;overflow:hidden}canvas{width:100%;height:100%}.side{overflow:auto}.progress{height:10px;background:#edf2f7;border-radius:20px;overflow:hidden}.progress>i{display:block;height:100%;background:#2f6b9a}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}table{width:100%;border-collapse:collapse;background:#fff}td,th{padding:10px;border-bottom:1px solid #e8edf1;text-align:left}@media(max-width:900px){.shell{grid-template-columns:1fr}nav{display:flex;overflow:auto;border-right:0;border-bottom:1px solid #ddd}.grid{grid-template-columns:1fr 1fr}.review-layout{grid-template-columns:1fr;height:auto}#canvasWrap{height:450px}}
</style></head><body><header><div class=brand>CompatibilizaBIM Studio</div><div id=projectName></div></header><div class=shell><nav id=nav><button data-page=import class=active>1. Importação</button><button data-page=config>2. Configuração</button><button data-page=review>3. Revisão</button><button data-page=profiles>4. Perfis CAD</button><button data-page=report>5. Relatório</button></nav><main>
<section id=import class="page active"><div class=title><div><h1>Importar projeto</h1><div class=muted>Disciplinas, formatos e arquivos do projeto</div></div><span id=ready></span></div><div class=card><b>Adicionar arquivos</b><p class=muted>O Studio monta o plano localmente; a conversão é executada pelo Core/bridge.</p><input id=filePick type=file multiple accept=".dwg,.dxf,.ifc,.json" onchange="addFiles(this.files)"></div><div id=sources></div></section>
<section id=config class=page><div class=title><div><h1>Configuração</h1><div class=muted>Parâmetros usados pelo reconhecimento e reconstrução 3D</div></div><button class="action primary" onclick="downloadConfig()">Exportar configuração</button></div><div class=grid id=configCards></div><div class=title style="margin-top:24px"><h2>Pavimentos</h2><button class=action onclick=addStorey()>Adicionar pavimento</button></div><table id=storeys></table></section>
<section id=review class=page><div class=title><div><h1>Revisar reconhecimento</h1><div class=muted>Confirme, edite ou rejeite elementos antes da exportação</div></div><div><button class=action onclick=undo()>Undo</button> <button class=action onclick=redo()>Redo</button> <button class=action onclick=saveWorkspaceProject()>Salvar no projeto</button> <button class="action primary" onclick=downloadCBIM()>Exportar CBIM revisado</button></div></div><div class=review-layout><div id=canvasWrap><canvas id=c></canvas></div><div class=side><div class=toolbar><select id=stateFilter onchange=renderReview()><option value="">Todos</option><option>auto</option><option>confirmed</option><option>edited</option><option>rejected</option></select><select id=typeFilter onchange=renderReview()><option value="">Todos tipos</option></select></div><div id=reviewStats></div><div id=elements></div></div></div></section>
<section id=profiles class=page><div class=title><div><h1>Aprendizado de perfil CAD</h1><div class=muted>Correções humanas podem virar regras reutilizáveis; reconhecimentos automáticos nunca ensinam sozinhos</div></div><button class="action primary" onclick=downloadLearnedProfile()>Exportar perfil aprendido</button></div><div class=card><b>Política de aprendizado</b><p>Somente elementos <code>confirmed</code> ou <code>edited</code> são elegíveis. Uma regra exige múltiplas observações consistentes antes de ser promovida.</p></div><div id=profileCandidates></div></section>
<section id=report class=page><div class=title><div><h1>Relatório final</h1><div class=muted>Qualidade, pendências e prontidão para exportação</div></div><button class="action primary" onclick=downloadReport()>Exportar relatório JSON</button></div><div class=grid id=metrics></div><h2>Elementos</h2><table id=counts></table><h2>Bloqueios</h2><div id=blockers></div></section>
</main></div><script>
let project='''+p+''', plan='''+pl+''', report='''+rp+''', selected=null, undoStack=[], redoStack=[];
const deep=x=>JSON.parse(JSON.stringify(x));document.getElementById('projectName').textContent=project.name;
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button,.page').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.page).classList.add('active');if(b.dataset.page==='review')setTimeout(draw,0)});
function badge(text,cls=''){return `<span class="badge ${cls}">${text}</span>`}
function inferDisc(name){let n=name.toUpperCase();if(/ARQ|ARQUIT|ARCH|PLANTA|LAYOUT/.test(n))return'architecture';if(/ESTR|EST_|STRUCT|CONCRETO|FORMA/.test(n))return'structure';if(/HID|AGUA|ÁGUA|ESGOTO|SANIT|PLUV|AF_|AQ_/.test(n))return'hydraulic';if(/INC|FIRE|SPRINK|HIDRANTE|SPK/.test(n))return'fire';return'unknown'}function inferFmt(name){let n=name.toLowerCase();if(n.endsWith('.dwg'))return'dwg';if(n.endsWith('.dxf'))return'dxf';if(n.endsWith('.ifc'))return'ifc';return'cbim'}function recomputePlan(){plan.ready=plan.sources.length>0&&plan.sources.every(s=>s.discipline!=='unknown');plan.warnings=plan.ready?[]:['Confirme a disciplina dos arquivos pendentes']}function addFiles(files){[...files].forEach(f=>{if(plan.sources.some(s=>s.name===f.name))return;let d=inferDisc(f.name);plan.sources.push({path:f.name,name:f.name,discipline:d,source_format:inferFmt(f.name),role:'primary',enabled:true,detected_by:'browser',warnings:d==='unknown'?['Discipline requires confirmation']:[]})});recomputePlan();renderImport()}function setDisc(i,v){plan.sources[i].discipline=v;plan.sources[i].warnings=v==='unknown'?['Discipline requires confirmation']:[];recomputePlan();renderImport()}function renderImport(){recomputePlan();document.getElementById('ready').innerHTML=badge(plan.ready?'Pronto':'Requer revisão',plan.ready?'ok':'warn');document.getElementById('sources').innerHTML=plan.sources.map((s,i)=>`<div class=source><b>${s.name}</b> ${badge(s.source_format.toUpperCase())} <select onchange="setDisc(${i},this.value)"><option ${s.discipline==='unknown'?'selected':''}>unknown</option><option ${s.discipline==='architecture'?'selected':''}>architecture</option><option ${s.discipline==='structure'?'selected':''}>structure</option><option ${s.discipline==='hydraulic'?'selected':''}>hydraulic</option><option ${s.discipline==='fire'?'selected':''}>fire</option></select><div class=muted>${s.path}</div>${s.warnings.map(w=>`<div>${badge(w,'warn')}</div>`).join('')}</div>`).join('')+plan.warnings.map(w=>`<div class=source>${badge(w,'warn')}</div>`).join('')}
function renderConfig(){let c=plan.config;document.getElementById('configCards').innerHTML=`<div class=card><div class=muted>Projeto</div><input value="${c.project_name}" onchange="plan.config.project_name=this.value;document.getElementById('projectName').textContent=this.value"></div><div class=card><div class=muted>Unidades</div><select onchange="plan.config.units=this.value"><option ${c.units==='m'?'selected':''}>m</option><option ${c.units==='mm'?'selected':''}>mm</option><option ${c.units==='cm'?'selected':''}>cm</option></select></div><div class=card><div class=muted>Coordenadas</div><input value="${c.coordinate_reference}" onchange="plan.config.coordinate_reference=this.value"></div><div class=card><div class=muted>Fabricante</div><input value="${c.preferred_manufacturer||''}" placeholder="Automático" onchange="plan.config.preferred_manufacturer=this.value||null"></div>`;document.getElementById('storeys').innerHTML='<tr><th>Pavimento</th><th>Cota</th><th>Altura</th><th></th></tr>'+c.storeys.map((s,i)=>`<tr><td><input value="${s.name}" onchange="plan.config.storeys[${i}].name=this.value"></td><td><input type=number step=.01 value="${s.elevation}" onchange="plan.config.storeys[${i}].elevation=+this.value"></td><td><input type=number step=.01 min=.01 value="${s.height}" onchange="plan.config.storeys[${i}].height=+this.value"></td><td><button class=action onclick="plan.config.storeys.splice(${i},1);renderConfig()">Remover</button></td></tr>`).join('')}function addStorey(){let c=plan.config.storeys,last=c[c.length-1],e=last?last.elevation+last.height:0;c.push({name:'Novo pavimento',elevation:e,height:2.8});renderConfig()}
function color(e){if(e.review_state==='rejected')return '#dc4a4a';if(e.review_state==='confirmed')return '#32b67a';if(e.review_state==='edited')return '#8a66cc';if(e.confidence>=.85)return '#42a5d9';if(e.confidence>=.6)return '#e0ad3b';return '#e66555'}
function pts(){let a=[];project.elements.forEach(e=>{if(e.start)a.push(e.start,e.end);if(e.center)a.push(e.center);if(e.position)a.push(e.position);if(e.path)a.push(...e.path);if(e.boundary)a.push(...e.boundary)});return a}
function draw(){let c=document.getElementById('c'),r=c.getBoundingClientRect();if(!r.width||!r.height)return;c.width=r.width*devicePixelRatio;c.height=r.height*devicePixelRatio;let all=pts();if(!all.length)return;let xs=all.map(q=>q.x),ys=all.map(q=>q.y),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),s=Math.min(c.width/(maxx-minx+1),c.height/(maxy-miny+1))*.82,tx=c.width*.09-minx*s,ty=c.height*.91+miny*s,ctx=c.getContext('2d'),P=q=>[q.x*s+tx,ty-q.y*s];ctx.clearRect(0,0,c.width,c.height);ctx.lineWidth=2.5*devicePixelRatio;project.elements.forEach(e=>{ctx.strokeStyle=color(e);ctx.fillStyle=color(e);ctx.lineWidth=(e.id===selected?5:2.5)*devicePixelRatio;if(e.start){let a=P(e.start),b=P(e.end);ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke()}if(e.path){ctx.beginPath();e.path.forEach((q,i)=>{let v=P(q);i?ctx.lineTo(...v):ctx.moveTo(...v)});ctx.stroke()}if(e.boundary){ctx.beginPath();e.boundary.forEach((q,i)=>{let v=P(q);i?ctx.lineTo(...v):ctx.moveTo(...v)});ctx.closePath();ctx.stroke()}if(e.position||e.center){let v=P(e.position||e.center);ctx.beginPath();ctx.arc(v[0],v[1],5*devicePixelRatio,0,Math.PI*2);ctx.fill()}})}
function snap(){undoStack.push(deep(project));redoStack=[]}function setState(id,state){snap();let e=project.elements.find(x=>x.id===id);e.review_state=state;selected=id;renderReview()}function undo(){if(!undoStack.length)return;redoStack.push(deep(project));project=undoStack.pop();renderReview()}function redo(){if(!redoStack.length)return;undoStack.push(deep(project));project=redoStack.pop();renderReview()}
function renderReview(){let sf=document.getElementById('stateFilter').value,tf=document.getElementById('typeFilter').value;let els=project.elements.filter(e=>(!sf||e.review_state===sf)&&(!tf||e.type===tf));let st={};project.elements.forEach(e=>st[e.review_state]=(st[e.review_state]||0)+1);document.getElementById('reviewStats').innerHTML='<div class=card>'+Object.entries(st).map(([k,v])=>`${badge(k)} <b>${v}</b>`).join(' &nbsp; ')+'</div>';document.getElementById('elements').innerHTML=els.map(e=>`<div class=element onclick="selected='${e.id}';draw()"><b>${e.type}</b> ${e.name||''}<div class=muted>${e.id} · ${Math.round(e.confidence*100)}% · ${e.review_state}</div><div><button class=action onclick="event.stopPropagation();setState('${e.id}','confirmed')">Confirmar</button><button class=action onclick="event.stopPropagation();setState('${e.id}','edited')">Marcar editado</button><button class=action onclick="event.stopPropagation();setState('${e.id}','rejected')">Rejeitar</button></div></div>`).join('');draw()}
function learnedProfile(){let grouped={};project.elements.filter(e=>['confirmed','edited'].includes(e.review_state)).forEach(e=>(e.source_refs||[]).forEach(r=>{if(!r.layer)return;let layer=r.layer.toUpperCase();grouped[layer]=grouped[layer]||{};grouped[layer][e.type]=(grouped[layer][e.type]||0)+1}));let rules=[];Object.entries(grouped).forEach(([layer,types])=>{let pairs=Object.entries(types).sort((a,b)=>b[1]-a[1]),total=pairs.reduce((a,x)=>a+x[1],0),[target,n]=pairs[0];if(total>=2&&n/total>=.8)rules.push({id:'learned-layer-'+layer.toLowerCase().replace(/[^a-z0-9]+/g,'-'),target,layer,block:null,match:'exact',system:null,defaults:{},priority:100})});return{name:'Perfil aprendido - '+project.name,version:'1.0',organization:plan.config.organization||null,rules}}function renderProfiles(){let p=learnedProfile(),all={};project.elements.filter(e=>['confirmed','edited'].includes(e.review_state)).forEach(e=>(e.source_refs||[]).forEach(r=>{if(r.layer)all[r.layer.toUpperCase()]=(all[r.layer.toUpperCase()]||0)+1}));document.getElementById('profileCandidates').innerHTML=Object.entries(all).sort().map(([k,n])=>`<div class=rule><b>${k}</b> ${badge(n+' observações',n>=2?'ok':'warn')}<div class=muted>${p.rules.some(r=>r.layer===k)?'Regra promovida':'Ainda não promovida'}</div></div>`).join('')||'<div class=card>Nenhuma regra elegível ainda.</div>'}function downloadLearnedProfile(){save(learnedProfile(),'learned-cad-profile.json')}
function recomputeReport(){let states={};project.elements.forEach(e=>states[e.review_state]=(states[e.review_state]||0)+1);report.review_states=states;report.pending_review=(states.auto||0)+(states.rejected||0);report.confirmed_or_edited=(states.confirmed||0)+(states.edited||0);report.completion_rate=project.elements.length?report.confirmed_or_edited/project.elements.length:1;report.blockers=[];if(states.auto)report.blockers.push(`${states.auto} elementos automáticos ainda requerem revisão`);if(states.rejected)report.blockers.push(`${states.rejected} elementos rejeitados permanecem`);report.ready_to_export=!report.blockers.length}
function renderReport(){recomputeReport();document.getElementById('metrics').innerHTML=`<div class=card><div class=metric>${report.total_elements}</div><div class=muted>Elementos</div></div><div class=card><div class=metric>${Math.round(report.mean_confidence*100)}%</div><div class=muted>Confiança</div></div><div class=card><div class=metric>${Math.round(report.completion_rate*100)}%</div><div class=muted>Revisado</div></div><div class=card><div class=metric>${report.pending_review}</div><div class=muted>Pendências</div></div>`;document.getElementById('counts').innerHTML='<tr><th>Tipo</th><th>Quantidade</th></tr>'+Object.entries(report.element_counts).map(([k,v])=>`<tr><td>${k}</td><td>${v}</td></tr>`).join('');document.getElementById('blockers').innerHTML=report.blockers.length?report.blockers.map(b=>`<div class=source>${badge(b,'bad')}</div>`).join(''):`<div class=source>${badge('Pronto para exportar','ok')}</div>`}
async function saveWorkspaceProject(){try{let r=await fetch('/api/project',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(project)});if(!r.ok)throw new Error(await r.text());let st=await r.json();alert('Projeto salvo. Revisão '+st.revision)}catch(e){alert('Modo arquivo local: use Exportar CBIM revisado ou abra o Studio pelo cbim-desktop para persistência automática.')}}function save(obj,name){let b=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click()}function downloadCBIM(){save(project,'reviewed.cbim.json')}function downloadConfig(){save(plan.config,'project-config.json')}function downloadReport(){recomputeReport();save(report,'conversion-report.json')}
let types=[...new Set(project.elements.map(e=>e.type))].sort();document.getElementById('typeFilter').innerHTML+types.map(t=>`<option>${t}</option>`).join('');window.onresize=draw;renderImport();renderConfig();renderReview();renderProfiles();renderReport();
</script></body></html>'''

def write_studio(project:CBIMProject,plan:ImportPlan,report:ConversionReport,path:str|Path)->Path:
    p=Path(path);p.write_text(build_studio_html(project,plan,report),encoding='utf-8');return p
